const $=id=>document.getElementById(id);let data,result,currentName='sensor-demo.csv';const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function demo(kind){let rows=[],x=1,y=1,z=1;let seed=42;const rnd=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};for(let i=0;i<1200;i++){if(kind==='lorenz'){for(let j=0;j<5;j++){let dx=10*(y-x),dy=x*(28-z)-y,dz=x*y-8*z/3;x+=.002*dx;y+=.002*dy;z+=.002*dz}rows.push([String(i*.01),String(x),String(y),String(z)])}else{let v=Math.sin(i*.07)+.25*Math.cos(i*.019);if(kind==='sensor'){v+=(rnd()-.5)*.18+(i>960?1.2:0);if(i===340||i===780)v+=5}rows.push([String(i+(kind==='sensor'&&i>600?3:0)),kind==='sensor'&&i%137===0?'':String(v)])}}load({headers:kind==='lorenz'?['time','x','y','z']:['time','signal'],rows},kind+'-demo.csv')}
function load(d,name){data=d;currentName=name;$('filename').textContent=name;$('rowcount').textContent=`${d.rows.length.toLocaleString()} rows · ${d.headers.length} columns`;$('signal').innerHTML=d.headers.map((h,i)=>`<option value="${i}">${esc(h)}</option>`).join('');$('time').innerHTML='<option value="-1">Row index (no timestamps)</option>'+d.headers.map((h,i)=>`<option value="${i}">${esc(h)}</option>`).join('');let ti=d.headers.findIndex(h=>/^(time|date|timestamp|datetime)$/i.test(h));$('time').value=ti;$('signal').value=d.headers.findIndex((h,i)=>i!==ti&&d.rows.some(r=>r[i].trim()!==''&&Number.isFinite(Number(r[i]))));render()}
function render(){try{$('error').textContent='';$('splitlabel').textContent=$('split').value+'%';result=ChaosLens.analyze(data,+$('signal').value,+$('time').value,+$('split').value);let r=result;$('stats').innerHTML=[['OBSERVATIONS',r.n.toLocaleString(),'Rows in selected signal'],['MISSING / INVALID',r.missing,`${(100*r.missing/r.n).toFixed(1)}% of observations`],['UNUSUAL POINTS',r.outliers.length,'4σ robust threshold · median / MAD'],['MEAN SHIFT',r.shift.toFixed(2)+' σ','Train versus test mean difference']].map(a=>`<div class="stat"><span>${a[0]}</span><strong>${a[1]}</strong><small>${a[2]}</small></div>`).join('');$('findings').innerHTML=r.findings.map(f=>`<article class="finding ${f.level}"><span class="status">${f.level==='warn'?'◉ REVIEW':f.level==='good'?'✓ CHECKED':'ⓘ CONTEXT'}</span><h3>${esc(f.title)}</h3><p>${esc(f.body)}</p></article>`).join('');drawAll();$('download').disabled=false}catch(e){result=null;$('error').textContent=e.message;$('stats').innerHTML='';$('findings').innerHTML='';['series','phase','acf'].forEach(id=>{let c=$(id);c.getContext('2d').clearRect(0,0,c.width,c.height)});$('download').disabled=true}}
function frame(id,xmin,xmax,ymin,ymax){let c=$(id),w=c.clientWidth,h=c.clientHeight,dpr=devicePixelRatio||1;c.width=w*dpr;c.height=h*dpr;let ctx=c.getContext('2d');ctx.scale(dpr,dpr);if(ymin===ymax){ymin-=1;ymax+=1}let pad=(ymax-ymin)*.08;ymin-=pad;ymax+=pad;let X=x=>45+(x-xmin)/(xmax-xmin||1)*(w-60),Y=y=>h-22-(y-ymin)/(ymax-ymin)*(h-35);ctx.font='9px system-ui';for(let k=0;k<5;k++){let v=ymin+(ymax-ymin)*k/4,yy=Y(v);ctx.strokeStyle='#edf0ef';ctx.beginPath();ctx.moveTo(45,yy);ctx.lineTo(w-15,yy);ctx.stroke();ctx.fillStyle='#87918d';ctx.fillText(v.toFixed(1),3,yy+3)}ctx.fillText(String(xmin),45,h-5);ctx.fillText(String(xmax),w-45,h-5);return {ctx,X,Y,w,h}}
function drawAll(){if(!result)return;let r=result,v=r.values,finite=v.filter(Number.isFinite),lo=Math.min(...finite),hi=Math.max(...finite),f=frame('series',0,v.length-1,lo,hi);f.ctx.strokeStyle='#24816a';f.ctx.lineWidth=1.2;f.ctx.beginPath();let pen=false;v.forEach((a,i)=>{if(!Number.isFinite(a)){pen=false;return}if(pen)f.ctx.lineTo(f.X(i),f.Y(a));else f.ctx.moveTo(f.X(i),f.Y(a));pen=true});f.ctx.stroke();f.ctx.setLineDash([4,4]);f.ctx.strokeStyle='#a99cc4';f.ctx.beginPath();f.ctx.moveTo(f.X(r.cut),12);f.ctx.lineTo(f.X(r.cut),f.h-22);f.ctx.stroke();f.ctx.setLineDash([]);f.ctx.fillStyle='#d99a55';r.outliers.forEach(i=>{f.ctx.beginPath();f.ctx.arc(f.X(i),f.Y(v[i]),3,0,Math.PI*2);f.ctx.fill()});let lag=Math.max(1,Math.min(100,Math.floor(+$('lag').value)||1));$('lag').value=lag;f=frame('phase',lo,hi,lo,hi);f.ctx.fillStyle='#24816a88';for(let i=0;i<v.length-lag;i++){if(Number.isFinite(v[i])&&Number.isFinite(v[i+lag]))f.ctx.fillRect(f.X(v[i]),f.Y(v[i+lag]),2,2)}f=frame('acf',1,r.acf.length,-1,1);f.ctx.strokeStyle='#24816a';f.ctx.lineWidth=2;r.acf.forEach((a,i)=>{f.ctx.beginPath();f.ctx.moveTo(f.X(i+1),f.Y(0));f.ctx.lineTo(f.X(i+1),f.Y(a));f.ctx.stroke()})}
function save(name,content,type){let url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('file').onchange=async e=>{let file=e.target.files[0];if(!file)return;try{if(file.size>5*1024*1024)throw Error('Please use a CSV smaller than 5 MB.');let d=ChaosLens.parse((await file.text()).replace(/^\uFEFF/,''));if(d.rows.length>50000)throw Error('Please use at most 50,000 data rows.');load(d,file.name)}catch(err){$('error').textContent=err.message}e.target.value=''};document.querySelectorAll('[data-demo]').forEach(b=>b.onclick=()=>demo(b.dataset.demo));['signal','time','split'].forEach(id=>$(id).oninput=render);$('lag').oninput=drawAll;window.addEventListener('resize',drawAll);$('series').onmousemove=e=>{if(!result)return;let box=$('series').getBoundingClientRect(),i=Math.max(0,Math.min(result.n-1,Math.round((e.clientX-box.left-45)/(box.width-60)*(result.n-1))));$('hover').textContent=`Row ${i+1} · ${data.headers[$('signal').value]} = ${Number.isFinite(result.values[i])?result.values[i].toPrecision(6):'missing / invalid'}`};$('download').onclick=()=>{if(!result)return;save('chaoslens-report.json',JSON.stringify({tool:'ChaosLens 0.1',file:currentName,signal:data.headers[$('signal').value],time:+$('time').value>=0?data.headers[$('time').value]:null,splitPercent:+$('split').value,methods:{unusual:'abs(x - median) / (1.4826 * MAD) > 4; unavailable if MAD = 0',shift:'abs(mean(test)-mean(train)) / population_std(all finite values)',sampling:'positive time increments more than 5% from median positive increment',limitations:'Heuristic diagnostics, not statistical proof of chaos or leakage.'},observations:result.n,missing:result.missing,outlierRowsOneBased:result.outliers.map(i=>i+1),mean:result.mean,std:result.sd,meanShift:result.shift,findings:result.findings},null,2),'application/json')};$('sample').onclick=()=>save(currentName,[data.headers,...data.rows].map(r=>r.map(s=>'"'+String(s).replace(/"/g,'""')+'"').join(',')).join('\n'),'text/csv');demo('sensor');
